import sailpoint.object.PasswordPolicy;
import sailpoint.api.PasswordGenerator;


String password = "Unknown";

 PasswordPolicy policy = context.getObjectByName(PasswordPolicy.class, "LDAP Password Policy");
 if (policy == null) {
     log.error("No password policy found for application OpenLDAP ");
 } else {
     PasswordGenerator generator = new PasswordGenerator(context);
     password = generator.generatePassword(policy);
 }

 return password;
